const fs = require('fs');
const path = require('path');

const folderPath = "C:\\Users\\itama\\Dropbox\\Docs Itamar\\Docs Itamar - Buisness\\חשבוניות - קבלות";
const processedFile = "C:\\Users\\itama\\Dropbox\\Docs Itamar\\Scripts\\Claude-code\\temp\\processed-invoices.json";

// Ensure temp dir exists
const tempDir = path.dirname(processedFile);
if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

// Load processed files list
let processed = [];
if (fs.existsSync(processedFile)) {
  try {
    processed = JSON.parse(fs.readFileSync(processedFile, 'utf8'));
  } catch (e) {
    processed = [];
  }
}

// Get all PDF files that haven't been processed
const files = fs.readdirSync(folderPath)
  .filter(f => {
    const fullPath = path.join(folderPath, f);
    const stat = fs.statSync(fullPath);
    return stat.isFile() && f.toLowerCase().endsWith('.pdf');
  })
  .filter(f => !processed.includes(f));

if (files.length === 0) {
  return [];
}

// Return each file as separate item for processing
return files.map(f => ({
  json: {
    fileName: f,
    filePath: path.join(folderPath, f)
  }
}));

const stdout = $input.first().json.stdout || "";
const stderr = $input.first().json.stderr || "";
const code = $input.first().json.code || 0;

if (code !== 0) {
  return {
    json: {
      error: "Command failed",
      stderr: stderr,
      fileName: $('List New PDF Files').item.json.fileName,
      filePath: $('List New PDF Files').item.json.filePath
    }
  };
}

let invoiceData;
try {
  invoiceData = JSON.parse(stdout);
} catch (error) {
  const jsonMatch = stdout.match(/```json\n([\s\S]*?)\n```/) || stdout.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      invoiceData = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    } catch (e) {
      return {
        json: {
          error: "Could not parse JSON",
          rawOutput: stdout,
          fileName: $('List New PDF Files').item.json.fileName,
          filePath: $('List New PDF Files').item.json.filePath
        }
      };
    }
  } else {
    return {
      json: {
        error: "No JSON found",
        rawOutput: stdout,
        fileName: $('List New PDF Files').item.json.fileName,
        filePath: $('List New PDF Files').item.json.filePath
      }
    };
  }
}

// Add original file info
invoiceData.originalFile = $('List New PDF Files').item.json.fileName;
invoiceData.originalFilePath = $('List New PDF Files').item.json.filePath;

return { json: invoiceData };

